498: // ── Dossiers racine créés via ➕ ─────────────────────────────────────────────
499: 
500: /** Les dossiers créés via le bouton ➕ sont vides : absents de l'arbre dérivé
501:  *  des fichiers scannés, ils seraient invisibles. Rendus ici, au même niveau
502:  *  que les dossiers scannés. Ceux qui reçoivent des fichiers via Scan
503:  *  redeviennent des nœuds normaux (exclus de ce rendu). */
504: function dirExistsInTree(tree: TreeNode, relPath: string): boolean {
505:   let node: TreeNode = tree;
506:   for (const seg of relPath.split('/')) {
507:     const next = node[seg] as TreeNode | undefined;
508:     if (!next || Array.isArray(next)) return false;
509:     node = next;
510:   }
511:   return true;
512: }
