557: // ── Squelette d'arbre partagé (EPIC-036 Phase 2) ─────────────────────────
558: 
559: /** Construction arbre → allTrees + compte total, partagée par sync-source et
560:  *  playlist-source (bloc identique au caractère près, doublon mesuré P2). */
561: export function buildSourceTrees(files: typeof state.sourceFiles): { allTrees: TreeAndDir[]; totalCount: number } {
562:   const allTrees: TreeAndDir[] = [];
563:   let totalCount = 0;
564:   for (const [dirPath, dirFiles] of Object.entries(files)) {
565:     const tree: TreeNode = {};
566:     for (const [filename, data] of Object.entries(dirFiles)) {
567:       const parts = data.path.split('/');
568:       totalCount++;
569:       if (parts.length <= 1) continue;
570:       let current: TreeNode = tree;
571:       for (let i = 0; i < parts.length - 1; i++) {
572:         const key = parts[i];
573:         if (!current[key]) current[key] = {};
574:         current = current[key] as TreeNode;
575:       }
576:       current.__files__ = current.__files__ || [];
577:       const entries = current.__files__;
578:       entries.push({
579:         filename,
580:         relPath: data.path,
581:         year: data.year,
582:         duration: data.duration,
583:         codec: data.codec,
584:         // EPIC-046 : le genre lu au scan suit l'entrée — sans lui la cellule
585:         // Style de la ligne ne pourrait afficher que « tag vide ». C'est le
586:         // seul chemin où l'information pouvait se perdre entre l'index et le DOM.
587:         genre: data.genre ?? null,
588:         baseDir: dirPath,
589:       } as FileEntry);
590:     }
591:     allTrees.push({ tree, dirPath });
592:   }
593:   return { allTrees, totalCount };
594: }
