596: /** Fin de render d'un panneau arbre : compteur d'en-tête + bandeau vide si le
597:  *  filtre ne garde rien. Partagée par sync-source et playlist-source. */
598: export function finishSourcePanel(
599:   container: HTMLElement,
600:   headerCountId: string,
601:   filteredCount: number | null,
602:   totalCount: number,
603: ): void {
604:   const headerCount = document.getElementById(headerCountId);
605:   if (filteredCount !== null) {
606:     if (headerCount) headerCount.textContent = `(${fmtCount(filteredCount)} / ${fmtCount(totalCount)})`;
607:     if (filteredCount === 0) appendPanelEmpty(container, 'Aucun dossier trouvé pour ce filtre.');
608:   } else if (headerCount) {
609:     headerCount.textContent = totalCount > 0 ? `(${fmtCount(totalCount)})` : '';
610:   }
611: }
