108:   const counts = new Map<string, number>();
109:   for (const entry of Object.values(files)) {
110:     const slash = entry.path.indexOf('/');
111:     if (slash <= 0) continue; // fichier à la racine
112:     const folder = entry.path.slice(0, slash);
113:     counts.set(folder, (counts.get(folder) ?? 0) + 1);
