.panel-active {
  border: 1px solid var(--accent) !important;
  box-shadow: inset 0 0 0 1px var(--accent);
}
.panel-header-count {
  font-size: 12px; color: var(--text-muted);
  font-weight: normal; margin-left: 8px;
}

/* ===== Bouton ➕ création dossier (header panneau Source Data) ======== */
.panel-add-btn {
  float: right;
  background: var(--bg-hover);
  color: var(--text-secondary);
  border: 1px solid var(--border-panel);
  border-radius: 3px;
  padding: 1px 8px;
  font-size: 12px;
  cursor: pointer;
}
.panel-add-btn:hover {
  background: var(--bg-focus);
  border-color: var(--border-emph);
  color: var(--text-primary);
}

/* ===== Chip de filtre collé (EPIC-037 P2) ============================ */
/* Le slot du chip est enfant du panneau (le conteneur scrollable) : il se colle
   en haut pendant le scroll de SA colonne — même pattern que
   #filter-slot-playlist-source (playlist.css) et #filter-slot-years.
   top:-10px = padding du panneau (le chip vient à ras du bord haut) ; les
   marges négatives latérales couvrent ce padding (aucune fente, pas de
   scrollbar horizontale : la boîte atteint exactement clientWidth) ; fond
   opaque = le contenu défile DERRIÈRE, z-index 3 au-dessus des lignes.
   PAS de marge négative en haut : la ligne d'état épars reste intacte au
   repos (le chip ne la chevauche qu'une fois collé). */
#panel-left > #filter-slot-sync-epars,
#panel-right > #filter-slot-sync-source {
  position: sticky; top: -10px; z-index: 3;
  background: var(--bg-panel);
  margin-left: -10px; margin-right: -10px;
  padding: 10px 10px 6px;
}

/* ===== Source Container (2-column layout) ============================ */
#source-container { column-count: 2; column-gap: 14px; }

/* ===== Directory Items =============================================== */
.directory {
  break-inside: avoid-column;
  font-weight: 600; color: var(--text-primary);
  cursor: pointer;
  padding: 3px 0 3px 14px;
  font-size: 14px;
}
/* Focus dossier (EPIC-039) : même grammaire que les lignes fichiers — boîte
   cyan 2 px (outline inset, zéro décalage) + barre d'accent 4 px + fond teinté.
   Déclaré APRÈS :hover/:active pour que le curseur gagne sur l'état survolé. */
.directory:hover    { background: var(--bg-hover); }
